import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiTrash2,
  FiEdit2,
  FiImage,
  FiUploadCloud,
  FiX,
  FiStar,
  FiGrid,
} from 'react-icons/fi';

import api from '../../services/api';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';


const AdminGallery = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const { t } = useLanguage();


  // =====================================================
  // STATE
  // =====================================================

  const [images, setImages] = useState([]);

  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [editingImage, setEditingImage] = useState(null);

  const [submitting, setSubmitting] = useState(false);


  const [formData, setFormData] = useState({
    title: '',
    category: '',
    description: '',
    is_featured: false,
    order: 0,
  });


  const [imageFile, setImageFile] = useState(null);

  const [imagePreview, setImagePreview] = useState('');


  // =====================================================
  // CATEGORIES
  // value = Backend value
  // label = Translated UI value
  // =====================================================

  const categories = [
    {
      value: 'School Activities',
      label: t('gallery.schoolActivities'),
    },
    {
      value: 'Classroom',
      label: t('gallery.classroom'),
    },
    {
      value: 'Graduation',
      label: t('gallery.graduation'),
    },
    {
      value: 'Trips',
      label: t('gallery.trips'),
    },
    {
      value: 'Special Events',
      label: t('gallery.specialEvents'),
    },
  ];


  // =====================================================
  // GET CATEGORY LABEL
  // =====================================================

  const getCategoryLabel = (value) => {

    const category = categories.find(
      (item) => item.value === value
    );

    return category
      ? category.label
      : value;

  };


  // =====================================================
  // FETCH IMAGES
  // =====================================================

  useEffect(() => {

    fetchImages();

  }, []);


  const fetchImages = async () => {

    try {

      setLoading(true);


      const response = await api.get(
        '/api/gallery/'
      );


      setImages(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Gallery error:',
        error
      );


      toast.error(
        t('gallery.loadFailed')
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    setEditingImage(null);


    setFormData({
      title: '',
      category: '',
      description: '',
      is_featured: false,
      order: 0,
    });


    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);

    setImagePreview('');

  };


  // =====================================================
  // OPEN ADD MODAL
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    setModalOpen(false);

    resetForm();

  };


  // =====================================================
  // IMAGE CHANGE
  // =====================================================

  const handleImageChange = (e) => {

    const file =
      e.target.files?.[0];


    if (!file) {
      return;
    }


    if (
      !file.type.startsWith('image/')
    ) {

      toast.error(
        t('gallery.invalidImage')
      );

      return;

    }


    // 5MB MAX

    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        t('gallery.imageTooLarge')
      );

      return;

    }


    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(file);


    setImagePreview(
      URL.createObjectURL(file)
    );

  };


  // =====================================================
  // REMOVE SELECTED IMAGE
  // =====================================================

  const removeSelectedImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);


    if (
      editingImage?.image_url
    ) {

      setImagePreview(
        editingImage.image_url
      );

    } else if (
      editingImage?.image
    ) {

      setImagePreview(
        editingImage.image
      );

    } else {

      setImagePreview('');

    }

  };


  // =====================================================
  // SUBMIT
  // =====================================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ===================================================
    // IMAGE REQUIRED WHEN CREATE
    // ===================================================

    if (
      !editingImage &&
      !imageFile
    ) {

      toast.error(
        t('gallery.imageRequired')
      );

      return;

    }


    try {

      setSubmitting(true);


      const payload =
        new FormData();


      // =================================================
      // DATA
      // =================================================

      payload.append(
        'title',
        formData.title || ''
      );


      payload.append(
        'category',
        formData.category || ''
      );


      payload.append(
        'description',
        formData.description || ''
      );


      payload.append(
        'is_featured',
        String(
          formData.is_featured
        )
      );


      payload.append(
        'order',
        String(
          formData.order ?? 0
        )
      );


      // =================================================
      // IMAGE
      // =================================================

      if (imageFile) {

        payload.append(
          'image_file',
          imageFile
        );

      }


      // =================================================
      // UPDATE
      // =================================================

      if (editingImage) {

        await api.put(
          `/api/gallery/${editingImage.id}`,
          payload,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          t(
            'gallery.updatedSuccess'
          )
        );

      }


      // =================================================
      // CREATE
      // =================================================

      else {

        await api.post(
          '/api/gallery/',
          payload,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          t(
            'gallery.createdSuccess'
          )
        );

      }


      handleCloseModal();


      await fetchImages();

    } catch (error) {

      console.error(
        'Gallery operation error:',
        error
      );


      const detail =
        error.response?.data?.detail;


      if (
        typeof detail === 'string'
      ) {

        toast.error(detail);

      } else if (
        Array.isArray(detail)
      ) {

        toast.error(
          detail
            .map(
              (item) =>
                item.msg
            )
            .join(', ')
        );

      } else {

        toast.error(
          t(
            'common.operationFailed'
          )
        );

      }

    } finally {

      setSubmitting(false);

    }

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (image) => {

    setEditingImage(image);


    setFormData({

      title:
        image.title || '',

      category:
        image.category || '',

      description:
        image.description || '',

      is_featured:
        Boolean(
          image.is_featured
        ),

      order:
        image.order || 0,

    });


    setImageFile(null);


    setImagePreview(
      image.image_url ||
      image.image ||
      ''
    );


    setModalOpen(true);

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (id) => {

    const confirmed =
      window.confirm(
        t(
          'gallery.deleteConfirm'
        )
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/gallery/${id}`
      );


      toast.success(
        t(
          'gallery.deletedSuccess'
        )
      );


      await fetchImages();

    } catch (error) {

      console.error(
        'Delete image error:',
        error
      );


      toast.error(
        typeof error.response?.data?.detail ===
          'string'
          ? error.response.data.detail
          : t(
              'gallery.deleteFailed'
            )
      );

    }

  };


  // =====================================================
  // COUNTS
  // =====================================================

  const featuredCount =
    images.filter(
      (image) =>
        image.is_featured
    ).length;


  const categoryCount =
    new Set(
      images
        .map(
          (image) =>
            image.category
        )
        .filter(Boolean)
    ).size;


  // =====================================================
  // RENDER
  // =====================================================

  return (

    <div className="w-full">


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >

            <FiImage size={18} />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {t(
                'gallery.title'
              )}
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {t(
                'gallery.subtitle'
              )}
            </p>

          </div>

        </div>


        {/* ADD IMAGE */}

        <button
          type="button"

          onClick={handleAdd}

          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
          "
        >

          <FiPlus size={17} />


          {t(
            'gallery.addImage'
          )}

        </button>

      </div>


      {/* =================================================
          SUMMARY CARDS
      ================================================== */}

      <div
        className="
          grid
          grid-cols-1
          sm:grid-cols-3
          gap-3
          mb-6
        "
      >


        {/* TOTAL */}

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'gallery.totalImages'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {images.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiImage size={18} />

            </div>

          </div>

        </div>


        {/* FEATURED */}

        <div
          className="
            bg-white
            border
            border-red-100
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'gallery.featuredImages'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {featuredCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiStar size={18} />

            </div>

          </div>

        </div>


        {/* CATEGORIES */}

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'gallery.categories'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {categoryCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiGrid size={18} />

            </div>

          </div>

        </div>

      </div>


      {/* =================================================
          GALLERY CONTAINER
      ================================================== */}

      <AdminCard
        className="
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >

        {/* TITLE */}

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
          "
        >

          <h2
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {t(
              'gallery.allImages'
            )}
          </h2>


          <p
            className="
              text-xs
              text-blue-300
              mt-1
            "
          >

            {images.length}{' '}

            {
              images.length === 1
                ? t(
                    'gallery.image'
                  )
                : t(
                    'gallery.images'
                  )
            }{' '}

            {t(
              'gallery.found'
            )}

          </p>

        </div>


        {/* =================================================
            LOADING
        ================================================== */}

        {
          loading ? (

            <div
              className="
                min-h-[300px]
                flex
                items-center
                justify-center
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-10
                    h-10
                    border-4
                    border-blue-200
                    border-t-blue-900
                    rounded-full
                    animate-spin
                    mx-auto
                  "
                />


                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-3
                  "
                >
                  {t(
                    'gallery.loading'
                  )}
                </p>

              </div>

            </div>

          ) : images.length === 0 ? (


            /* ===============================================
                EMPTY STATE
            ================================================ */

            <div
              className="
                min-h-[320px]
                flex
                items-center
                justify-center
                p-6
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-16
                    h-16
                    bg-blue-50
                    text-blue-900
                    rounded-full
                    flex
                    items-center
                    justify-center
                    mx-auto
                    mb-4
                  "
                >

                  <FiImage size={26} />

                </div>


                <h3
                  className="
                    text-base
                    font-bold
                    text-blue-900
                  "
                >
                  {t(
                    'gallery.noImages'
                  )}
                </h3>


                <p
                  className="
                    text-sm
                    text-blue-400
                    mt-1
                    mb-4
                  "
                >
                  {t(
                    'gallery.addFirstImage'
                  )}
                </p>


                <button
                  type="button"

                  onClick={handleAdd}

                  className="
                    inline-flex
                    items-center
                    gap-2
                    bg-red-600
                    text-white
                    px-4
                    py-2.5
                    rounded-lg
                    text-sm
                    font-semibold
                    hover:bg-red-700
                    transition
                  "
                >

                  <FiPlus />


                  {t(
                    'gallery.addImage'
                  )}

                </button>

              </div>

            </div>

          ) : (


            /* ===============================================
                IMAGE GRID
            ================================================ */

            <div
              className="
                p-4
                md:p-5
                grid
                grid-cols-1
                sm:grid-cols-2
                lg:grid-cols-3
                xl:grid-cols-4
                gap-4
              "
            >

              {
                images.map(
                  (image) => (

                    <div
                      key={image.id}

                      className="
                        group
                        bg-white
                        border
                        border-blue-200
                        rounded-xl
                        overflow-hidden
                        shadow-sm
                        hover:shadow-lg
                        hover:-translate-y-1
                        transition-all
                        duration-300
                      "
                    >


                      {/* =====================================
                          IMAGE
                      ====================================== */}

                      <div
                        className="
                          relative
                          w-full
                          h-[190px]
                          bg-blue-50
                          overflow-hidden
                        "
                      >

                        <img
                          src={
                            image.image_url ||
                            image.image
                          }

                          alt={
                            image.title ||
                            t(
                              'gallery.image'
                            )
                          }

                          className="
                            w-full
                            h-full
                            object-cover
                            group-hover:scale-105
                            transition-transform
                            duration-500
                          "

                          onError={(e) => {

                            e.currentTarget.style.display =
                              'none';

                          }}
                        />


                        {/* IMAGE FALLBACK */}

                        <div
                          className="
                            absolute
                            inset-0
                            -z-10
                            flex
                            items-center
                            justify-center
                            bg-blue-50
                            text-blue-300
                          "
                        >

                          <FiImage size={35} />

                        </div>


                        {/* FEATURED */}

                        {
                          image.is_featured && (

                            <div
                              className="
                                absolute
                                top-3
                                left-3
                                inline-flex
                                items-center
                                gap-1.5
                                px-2.5
                                py-1.5
                                bg-red-600
                                text-white
                                rounded-lg
                                text-[10px]
                                font-bold
                                shadow-sm
                              "
                            >

                              <FiStar
                                size={11}
                                className="fill-current"
                              />


                              {t(
                                'gallery.featured'
                              )}

                            </div>

                          )
                        }


                        {/* CATEGORY */}

                        {
                          image.category && (

                            <div
                              className="
                                absolute
                                bottom-3
                                left-3
                                max-w-[75%]
                                px-2.5
                                py-1.5
                                bg-blue-900/90
                                backdrop-blur-sm
                                text-white
                                rounded-lg
                                text-[10px]
                                font-semibold
                                truncate
                              "
                            >

                              {
                                getCategoryLabel(
                                  image.category
                                )
                              }

                            </div>

                          )
                        }

                      </div>


                      {/* =====================================
                          CONTENT
                      ====================================== */}

                      <div className="p-4">

                        <h3
                          className="
                            text-sm
                            font-bold
                            text-blue-900
                            truncate
                          "
                        >

                          {
                            image.title ||
                            t(
                              'gallery.untitledImage'
                            )
                          }

                        </h3>


                        {
                          image.description ? (

                            <p
                              className="
                                text-xs
                                text-blue-400
                                mt-1.5
                                line-clamp-2
                                leading-5
                                min-h-[40px]
                              "
                            >
                              {
                                image.description
                              }
                            </p>

                          ) : (

                            <p
                              className="
                                text-xs
                                text-blue-300
                                mt-1.5
                                min-h-[40px]
                              "
                            >
                              {t(
                                'gallery.noDescription'
                              )}
                            </p>

                          )
                        }


                        {/* ACTIONS */}

                        <div
                          className="
                            flex
                            items-center
                            justify-between
                            pt-3
                            mt-3
                            border-t
                            border-blue-200
                          "
                        >

                          <span
                            className="
                              text-[10px]
                              text-blue-300
                            "
                          >

                            {t(
                              'gallery.order'
                            )}:{' '}

                            {
                              image.order ||
                              0
                            }

                          </span>


                          <div
                            className="
                              flex
                              items-center
                              gap-2
                            "
                          >

                            {/* EDIT */}

                            <button
                              type="button"

                              onClick={() =>
                                handleEdit(
                                  image
                                )
                              }

                              className="
                                w-8
                                h-8
                                flex
                                items-center
                                justify-center
                                bg-blue-50
                                text-blue-900
                                rounded-lg
                                hover:bg-blue-900
                                hover:text-white
                                transition
                              "

                              title={
                                t(
                                  'common.edit'
                                )
                              }
                            >

                              <FiEdit2
                                size={14}
                              />

                            </button>


                            {/* DELETE */}

                            <button
                              type="button"

                              onClick={() =>
                                handleDelete(
                                  image.id
                                )
                              }

                              className="
                                w-8
                                h-8
                                flex
                                items-center
                                justify-center
                                bg-red-50
                                text-red-600
                                rounded-lg
                                hover:bg-red-600
                                hover:text-white
                                transition
                              "

                              title={
                                t(
                                  'common.delete'
                                )
                              }
                            >

                              <FiTrash2
                                size={14}
                              />

                            </button>

                          </div>

                        </div>

                      </div>

                    </div>

                  )
                )
              }

            </div>

          )
        }

      </AdminCard>


      {/* =================================================
          ADD / EDIT MODAL
      ================================================== */}

      <AdminModal
        isOpen={modalOpen}

        onClose={
          handleCloseModal
        }

        title={
          editingImage
            ? t(
                'gallery.editImage'
              )
            : t(
                'gallery.addImage'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-4">


            {/* ===========================================
                TITLE
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'gallery.imageTitle'
                )}
              </label>


              <input
                type="text"

                value={
                  formData.title
                }

                onChange={(e) =>
                  setFormData({
                    ...formData,

                    title:
                      e.target.value,
                  })
                }

                placeholder={
                  t(
                    'gallery.titlePlaceholder'
                  )
                }

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* ===========================================
                CATEGORY + ORDER
            ============================================ */}

            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >


              {/* CATEGORY */}

              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {t(
                    'gallery.category'
                  )}
                </label>


                <select
                  value={
                    formData.category
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      category:
                        e.target.value,
                    })
                  }

                  className="
                    w-full
                    h-11
                    px-3.5
                    border
                    border-blue-200
                    rounded-lg
                    bg-white
                    text-sm
                    text-blue-900
                    outline-none
                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10
                  "
                >

                  <option value="">

                    {t(
                      'gallery.selectCategory'
                    )}

                  </option>


                  {
                    categories.map(
                      (category) => (

                        <option
                          key={
                            category.value
                          }

                          value={
                            category.value
                          }
                        >

                          {
                            category.label
                          }

                        </option>

                      )
                    )
                  }

                </select>

              </div>


              {/* ORDER */}

              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {t(
                    'gallery.displayOrder'
                  )}
                </label>


                <input
                  type="number"

                  min="0"

                  value={
                    formData.order
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      order:
                        Number(
                          e.target.value
                        ) || 0,
                    })
                  }

                  className="
                    w-full
                    h-11
                    px-3.5
                    border
                    border-blue-200
                    rounded-lg
                    text-sm
                    text-blue-900
                    outline-none
                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10
                  "
                />

              </div>

            </div>


            {/* ===========================================
                IMAGE UPLOAD
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >

                {
                  editingImage
                    ? t(
                        'gallery.changeImage'
                      )
                    : t(
                        'gallery.uploadImage'
                      )
                }


                {
                  !editingImage && (

                    <span
                      className="
                        text-red-600
                      "
                    >
                      {' '}*
                    </span>

                  )
                }

              </label>


              {
                !imagePreview ? (

                  <label
                    className="
                      min-h-[150px]
                      border-2
                      border-dashed
                      border-blue-200
                      rounded-xl
                      bg-blue-50
                      flex
                      flex-col
                      items-center
                      justify-center
                      cursor-pointer
                      hover:border-blue-400
                      transition-all
                    "
                  >

                    <div
                      className="
                        w-11
                        h-11
                        bg-blue-50
                        text-blue-900
                        rounded-xl
                        flex
                        items-center
                        justify-center
                        mb-2
                      "
                    >

                      <FiUploadCloud
                        size={21}
                      />

                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'gallery.clickUpload'
                      )}
                    </p>


                    <p
                      className="
                        text-[11px]
                        text-blue-300
                        mt-1
                      "
                    >
                      {t(
                        'gallery.imageFormats'
                      )}
                    </p>


                    <input
                      type="file"

                      accept="image/*"

                      onChange={
                        handleImageChange
                      }

                      className="hidden"
                    />

                  </label>

                ) : (

                  <div
                    className="
                      relative
                      w-full
                      h-[220px]
                      bg-blue-50
                      rounded-xl
                      overflow-hidden
                      border
                      border-blue-200
                    "
                  >

                    <img
                      src={
                        imagePreview
                      }

                      alt={
                        t(
                          'gallery.preview'
                        )
                      }

                      className="
                        w-full
                        h-full
                        object-cover
                      "
                    />


                    {/* REMOVE */}

                    <button
                      type="button"

                      onClick={
                        removeSelectedImage
                      }

                      className="
                        absolute
                        top-3
                        right-3
                        w-8
                        h-8
                        bg-black/60
                        text-white
                        rounded-full
                        flex
                        items-center
                        justify-center
                        hover:bg-red-600
                        transition
                      "

                      title={
                        t(
                          'common.remove'
                        )
                      }
                    >

                      <FiX size={15} />

                    </button>


                    {/* CHANGE */}

                    <label
                      className="
                        absolute
                        left-3
                        bottom-3
                        inline-flex
                        items-center
                        gap-2
                        bg-white
                        text-blue-900
                        px-3
                        py-2
                        rounded-lg
                        shadow-md
                        text-xs
                        font-semibold
                        cursor-pointer
                        hover:bg-blue-900
                        hover:text-white
                        transition
                      "
                    >

                      <FiUploadCloud />


                      {t(
                        'gallery.changeImage'
                      )}


                      <input
                        type="file"

                        accept="image/*"

                        onChange={
                          handleImageChange
                        }

                        className="hidden"
                      />

                    </label>

                  </div>

                )
              }


              {
                editingImage &&
                !imageFile && (

                  <p
                    className="
                      text-[11px]
                      text-blue-300
                      mt-1.5
                    "
                  >
                    {t(
                      'gallery.keepCurrentImage'
                    )}
                  </p>

                )
              }

            </div>


            {/* ===========================================
                DESCRIPTION
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'gallery.description'
                )}
              </label>


              <textarea
                value={
                  formData.description
                }

                onChange={(e) =>
                  setFormData({
                    ...formData,

                    description:
                      e.target.value,
                  })
                }

                rows="3"

                placeholder={
                  t(
                    'gallery.descriptionPlaceholder'
                  )
                }

                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* ===========================================
                FEATURED
            ============================================ */}

            <label
              className={`
                flex
                items-center
                gap-3
                p-3.5
                border
                rounded-xl
                cursor-pointer
                transition-all

                ${
                  formData.is_featured
                    ? `
                      border-red-300
                      bg-red-50
                    `
                    : `
                      border-blue-200
                      bg-white
                    `
                }
              `}
            >

              <input
                type="checkbox"

                checked={
                  formData.is_featured
                }

                onChange={(e) =>
                  setFormData({
                    ...formData,

                    is_featured:
                      e.target.checked,
                  })
                }

                className="
                  w-4
                  h-4
                  accent-red-500
                "
              />


              <div
                className="
                  w-9
                  h-9
                  bg-red-50
                  text-red-600
                  rounded-lg
                  flex
                  items-center
                  justify-center
                "
              >

                <FiStar size={16} />

              </div>


              <div>

                <p
                  className="
                    text-sm
                    font-semibold
                    text-blue-900
                  "
                >
                  {t(
                    'gallery.featured'
                  )}
                </p>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-0.5
                  "
                >
                  {t(
                    'gallery.featuredDescription'
                  )}
                </p>

              </div>

            </label>

          </div>


          {/* =================================================
              FOOTER BUTTONS
          ================================================== */}

          <div
            className="
              mt-6
              pt-4
              border-t
              border-blue-200
              flex
              items-center
              justify-end
              gap-3
            "
          >

            <button
              type="button"

              onClick={
                handleCloseModal
              }

              disabled={
                submitting
              }

              className="
                h-10
                px-4
                bg-white
                border
                border-blue-200
                text-blue-400
                rounded-lg
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >
              {t(
                'common.cancel'
              )}
            </button>


            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                min-w-[115px]
                h-10
                px-5
                bg-red-600
                text-white
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-700
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >

              {
                submitting
                  ? editingImage
                    ? t(
                        'gallery.updating'
                      )
                    : t(
                        'gallery.uploading'
                      )
                  : editingImage
                  ? t(
                      'gallery.updateImage'
                    )
                  : t(
                      'gallery.addImage'
                    )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminGallery;
